/* Visual planning and country-specific consequences for a middle-school council. */
const societyBaseRole=renderRole,societyBaseRender=render;
const foodLabels={people:'People',army:'Army',research:'Experiments',reserve:'Save for later'},foodIcons={people:'👨‍👩‍👧',army:'🛡',research:'🧪',reserve:'🏺'};
function foodRows(plan){return Society.foodKeys.map(k=>{const need=plan.needs[k]||0,limit=plan.limits[k],covered=limit+1e-8>=need;return `<div class="food-forecast ${covered?'':'at-risk'}"><span>${foodIcons[k]} ${foodLabels[k]}</span><b>${limit.toFixed(1)} food</b><small>${k==='reserve'?'Protected from these uses':`${covered?'✓':'⚠'} ${need.toFixed(1)} requested`}</small></div>`;}).join('');}
renderRole=function(){societyBaseRole();const c=ctry();if(role==='economy'){const panel=document.createElement('section');panel.className='allocation-panel food-panel';panel.id='foodPanel';panel.innerHTML=`<div class="section-kicker">FEED YOUR PLAN</div><h3>Where does the food go?</h3><p>Divide <b>stored food + this turn's harvest</b>. A share is a spending limit, not food automatically used. Unused portions return to storage.</p><form id="foodAllocationForm"><div class="allocation-presets"><button type="button" data-food-preset="65,20,10,5">Balanced</button><button type="button" data-food-preset="80,10,5,5">People first</button><button type="button" data-food-preset="45,40,10,5">Army focus</button><button type="button" data-food-preset="50,10,10,30">Save food</button></div><div class="allocation-bar" id="foodBar" aria-hidden="true"></div><div class="share-grid">${Society.foodKeys.map(k=>`<label>${foodIcons[k]} ${foodLabels[k]} %<input data-food-share="${k}" id="food-${k}" type="number" min="0" max="100" step="1" value="${c.foodShares[k]}"></label>`).join('')}</div>${field('Portions for people','foodRations',Object.entries(Society.rations).map(([k,p])=>[k,p.name+' · '+Math.round(p.amount*100)+'% food need · '+(p.morale>=0?'+':'')+p.morale+' happiness']),c.rations,'Generous portions help happiness only if people receive the whole serving. Small portions reduce needs but lower happiness. Underfunded portions cause a shortage.')}<p id="foodAllocationStatus" class="allocation-status" role="status"></p><button id="applyFood" class="primary" type="submit">Apply food plan</button></form><div id="foodPreview" class="food-preview"></div><p class="micro-help">Preview assumes current positions and planned output. Movement, spending, and new recruits can change needs. Army requests refill carried supplies; cut-off troops cannot receive food. Research requests may fall if money is short. Trades and events happen afterward; storage limits and 1% food spoilage still apply.</p></section>`;$('rolePanel').querySelector('.role-checklist').after(panel);
const values=()=>Object.fromEntries(Society.foodKeys.map(k=>[k,Number($('food-'+k).value)]));function preview(){const shares=values(),sum=Object.values(shares).reduce((n,v)=>n+v,0),valid=Society.shares(shares,Society.foodKeys),draft={...c,foodShares:valid?shares:c.foodShares,rations:$('foodRations').value},plan=Society.foodPlan(state,draft);$('foodBar').innerHTML=Society.foodKeys.map(k=>`<span class="segment-${k}" style="flex:${Math.max(0,shares[k])||0}"></span>`).join('');const changed=JSON.stringify(shares)!==JSON.stringify(c.foodShares)||draft.rations!==c.rations;$('foodAllocationStatus').textContent=valid?(state.phase!=='implement'?'Plan locked until the next Implement phase.':changed?'100% allocated · Unsaved changes. Apply to save.':'✓ Saved food plan · 100% allocated.'):`${Number.isFinite(sum)?sum:0}% of 100% allocated. Adjust the shares to total 100%.`;$('applyFood').disabled=!valid||state.phase!=='implement';$('foodPreview').innerHTML=`<h4>Projected food to divide: ${plan.available.toFixed(1)}</h4>${foodRows(plan)}${Object.keys(plan.needs).some(k=>plan.needs[k]>plan.limits[k]+1e-8)?'<p class="allocation-warning">⚠ A purpose needs more than its share. Other portions stay protected, even if food remains in storage.</p>':''}`;}
$('foodAllocationForm').onsubmit=e=>{e.preventDefault();action(()=>Society.setFood(state,active,values(),$('foodRations').value),'Food allocation saved.');};panel.querySelectorAll('[data-food-share]').forEach(e=>e.oninput=preview);$('foodRations').onchange=preview;panel.querySelectorAll('[data-food-preset]').forEach(b=>b.onclick=()=>{b.dataset.foodPreset.split(',').forEach((v,i)=>$('food-'+Society.foodKeys[i]).value=v);preview();});preview();if(state.phase!=='implement')panel.querySelectorAll('input,select,button').forEach(e=>e.disabled=true);}
if(role==='military'){const panel=document.createElement('section');panel.className='mini-card service-panel';const plan=Society.foodPlan(state,c);panel.innerHTML=`<h3>🛡 Supplies & service</h3><p>Economy set aside <b>${c.foodShares.army}%</b> of food for the army: about <b>${plan.limits.army.toFixed(1)}</b> next Results. Connected regiments currently request ${plan.needs.army.toFixed(1)} to refill packs. Smaller regiment IDs receive food first when this share is short.</p><p>Service law: <b>${Society.laws.service.options[c.laws.service].name}</b>. ${c.laws.service==='conscription'?'10 residents can become infantry each turn. The law lowers happiness and raises unrest.':'Recruit volunteers with your allowance.'}</p>${c.laws.service==='conscription'?field('Preferred regiment for drafted troops','draftRegiment',[['','Any eligible home regiment'],...state.regiments.filter(r=>r.country===active).map(r=>[r.id,r.name])],c.draftRegiment??'','Must be at a home city or town with 35 residents. Otherwise an eligible home regiment receives them, or a reserve forms in a home settlement.'):''}`;$('rolePanel').querySelector('.role-checklist').after(panel);if($('draftRegiment')){$('draftRegiment').disabled=state.phase!=='implement';$('draftRegiment').onchange=e=>action(()=>c.draftRegiment=e.target.value?Number(e.target.value):null);}}};
render=function(){societyBaseRender();const c=ctry(),risk=Society.risk(c),plan=Society.foodPlan(state,c);let pulse=$('realmPulse');if(!pulse){pulse=document.createElement('section');pulse.id='realmPulse';pulse.className='realm-pulse';document.querySelector('.workspace').before(pulse);}const last=c.foodReport,events=state.events.filter(e=>e.country===active).slice(0,4),unrestLabel=c.unrest<25?'Calm':c.unrest<55?'Concerned':'Restless';pulse.innerHTML=`<div class="pulse-grid"><article><span class="section-kicker">PUBLIC MOOD</span><h3>😊 ${Math.round(c.morale)} happiness <span> / 100</span></h3><p>Happier communities attract residents. Schools, laws and food all matter.${c.policyReport?` Last policy/food change: <b>${c.policyReport.moraleBefore.toFixed(0)} → ${c.policyReport.moraleAfter.toFixed(0)}</b> before events.`:''}</p></article><article class="unrest-${c.unrest<25?'low':c.unrest<55?'medium':'high'}"><span class="section-kicker">SOCIAL PRESSURE</span><h3>${c.unrest<25?'🌿':'📣'} ${unrestLabel} <span>· ${Math.round(c.unrest)}/100 unrest</span></h3><meter min="0" max="100" low="25" high="55" optimum="0" value="${c.unrest}" aria-label="Unrest level"></meter><p>About <b>${Math.round(risk.negative*100)}%</b> chance of a negative social event next turn at this unrest. Policies can change it before the roll.</p></article><article><span class="section-kicker">FOOD CHECK</span><h3>🌾 ${last?'Last turn’s allocation':'Next turn’s plan'}</h3>${last?`<p>People received <b>${last.civilianFed.toFixed(1)} / ${last.civilianNeed.toFixed(1)}</b> food. Army refills used <b>${last.used.army.toFixed(1)}</b>; experiments used <b>${last.used.research.toFixed(1)}</b>.</p>`:`<p>People need <b>${plan.needs.people.toFixed(1)}</b>; their share allows <b>${plan.limits.people.toFixed(1)}</b>. Economy sets the split.</p>`}</article></div><details class="event-history" ${state.phase==='results'?'open':''}><summary>🌍 Life in ${esc(c.name)} · ${events.length?'recent events':'no events yet'} <span>Social choices + natural surprises</span></summary><p>Each turn: 18% chance of a natural event (half helpful, half difficult). Social events depend on unrest. Chances are game rules, not forecasts. A quiet turn is possible; saved turns do not reroll.</p><div class="event-grid">${events.map(e=>{const d=Society.eventCatalog[e.key];return `<article class="event-card ${d.tone}"><span class="event-icon">${d.icon}</span><div><small>Turn ${e.turn} · ${d.kind} · ${d.tone==='positive'?'Helpful':'Challenge'}</small><h4>${d.name}</h4><p>${Object.entries(e.effects).map(([k,n])=>`${n>=0?'+':''}${n.toFixed(1)} ${k}`).join(' · ')}</p></div></article>`;}).join('')||'<p>No events recorded for this country yet. Plan together, then resolve Results.</p>'}</div></details>`;};
render();
